pub fn parse_datetime_input_with_reference(
    input: &str,
    reference_date: NaiveDate,
) -> ResultWithDefaultError<DateTime<Utc>> {
    let value = input.trim();

    // Time-only formats: use reference_date instead of today
    let time_formats = ["%H:%M:%S", "%H:%M"];
    for format in time_formats {
        if let Ok(time) = NaiveTime::parse_from_str(value, format) {
            let naive = NaiveDateTime::new(reference_date, time);
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
    }

    // Fall back to the standard parser for all other formats
    parse_datetime_input(input)
}

pub fn normalize_time_entry_list_filters(
    since: Option<String>,
    until: Option<String>,
) -> ResultWithDefaultError<(Option<String>, Option<String>)> {
    let since = since
        .as_deref()
        .map(|value| normalize_time_entry_list_filter(value, false))
        .transpose()?;
    let until = until
        .as_deref()
        .map(|value| normalize_time_entry_list_filter(value, true))
        .transpose()?;

    // Official Toggl API requires both start_date and end_date.
    // Auto-fill missing --until to now, or missing --since to epoch.
    let since = since.or_else(|| {
        if until.is_some() {
            Some("1970-01-01T00:00:00Z".to_string())
        } else {
            None
        }
    });
    let until = until.or_else(|| {
        if since.is_some() {
            Some(Utc::now().format("%Y-%m-%dT%H:%M:%SZ").to_string())
        } else {
            None
        }
    });

    // Validate that --since is not after --until
    if let (Some(since_val), Some(until_val)) = (&since, &until) {
        if since_val > until_val {
            return Err(Box::new(ArgumentError::InvalidTimeRange(
                "the --since date/time must not be after the --until date/time. \
                 Got reversed range: --since was later than --until. \
                 Hint: swap the values or use a valid date range."
                    .to_string(),
            )));
        }
    }

    Ok((since, until))
}

fn normalize_time_entry_list_filter(input: &str, is_until: bool) -> ResultWithDefaultError<String> {
    let value = input.trim();
    if let Ok(date) = NaiveDate::parse_from_str(value, "%Y-%m-%d") {
        let boundary_date = if is_until {
            match date.succ_opt() {
                Some(next_date) => next_date,
                None => return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            }
        } else {
            date
        };
        let naive = match boundary_date.and_hms_opt(0, 0, 0) {
            Some(naive) => naive,
            None => return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
        };
        // Convert local time to UTC for API, ensuring proper RFC3339 format
        return match Local.from_local_datetime(&naive) {
            LocalResult::Single(local_dt) => {
                let utc_dt = local_dt.with_timezone(&Utc);
                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
            }
            LocalResult::None => {
                // Handle DST gaps by using UTC directly
                let utc_dt = Utc.from_utc_datetime(&naive);
                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
            }
            LocalResult::Ambiguous(dt1, _dt2) => {
                // Handle DST overlaps by using the first option
                let utc_dt = dt1.with_timezone(&Utc);
                Ok(utc_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string())
            }
        };
    }

    }
}

fn setup_working_directory(directory: Option<std::path::PathBuf>) -> ResultWithDefaultError<()> {
    if let Some(dir) = directory {
        if !dir.exists() {
            return Err(Box::new(error::ArgumentError::DirectoryNotFound(dir)));
        }
        if !dir.is_dir() {
            return Err(Box::new(error::ArgumentError::NotADirectory(dir)));
        }
        std::env::set_current_dir(dir).expect("Couldn't set current directory");
    }
    Ok(())
}

async fn execute_entry_command(
    action: EntryAction,
    proxy: Option<String>,
    picker: Box<dyn picker::ItemPicker>,
) -> ResultWithDefaultError<()> {
    // Validate required arguments BEFORE creating the API client to avoid
    // unnecessary keychain/storage access for validation failures.
    match &action {
        EntryAction::Show { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'show' requires an entry ID or --current flag. Run `toggl entry list` or `toggl entry running` to find one.".to_string(),
            )));
        }
        EntryAction::Update { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'edit' requires an entry ID or --current flag. Example: toggl entry edit --current -d \"New description\"".to_string(),
            )));
        }
        EntryAction::Update {
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            ..
        } if description.is_none()
            && billable.is_none()
            && project.is_none()
            && task.is_none()
            && tags.is_none()
            && start.is_none()
            && end.is_none() =>
        {
            return Err(Box::new(error::ArgumentError::MissingUpdateFields(
                "No fields specified to update. Use -d, -p, -t, --billable, --tags, --start, or --end to specify what to change.".to_string(),
            )));
        }
        EntryAction::Delete { id, current, .. } if id.is_none() && !current => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'delete' requires an entry ID or --current flag. Run `toggl entry list` to find entry IDs.".to_string(),
            )));
        }
        EntryAction::BulkEdit { json: None, .. } => {
            return Err(Box::new(error::ArgumentError::MissingArgument(
                "'bulk-edit' requires --json flag with JSON payload".to_string(),
            )));
        }
        _ => {}
    }

    let api_client = get_api_client(proxy.clone())?;

    match action {
        EntryAction::Current { json } => RunningTimeEntryCommand::execute(api_client, json).await,
        EntryAction::List {
            number,
            json,
            since,
            until,
        } => ListCommand::execute(api_client, number, json, since, until, None).await,
        EntryAction::Stop { json } => {
            StopCommand::execute(&api_client, StopCommandOrigin::CommandLine, json).await?;
            Ok(())
        }
        EntryAction::Start {
            billable,
            description,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            StartCommand::execute(
                api_client,
                picker,
                description,
                project,
                task,
                tags,
                billable,
                false,
                start,
                end,
                json,
            )
            .await
        }
        EntryAction::Resume { id, json } => {
            ContinueCommand::execute(api_client, None, id, json).await
        }
        EntryAction::Show { id, current, json } => {
            if current {
                // Get the current running entry and show it
                match api_client.get_current_time_entry_minimal().await? {
                    Some(entry) => ShowCommand::execute(api_client, entry.id, json).await,
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                // id is guaranteed Some due to validation above
                ShowCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Update {
            id,
            current,
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            if current {
                // Check if there's a running entry before attempting edit
                match api_client.get_current_time_entry_minimal().await? {
                    Some(_) => {
                        // There's a running entry, let EditCommand handle it with id=None
                        EditCommand::execute(
                            api_client,
                            None,
                            description,
                            billable,
                            project,
                            task,
                            tags,
                            start,
                            end,
                            json,
                        )
                        .await
                    }
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                EditCommand::execute(
                    api_client,
                    id,
                    description,
                    billable,
                    project,
                    task,
                    tags,
                    start,
                    end,
                    json,
                )
                .await
            }
        }
        EntryAction::Delete { id, current, json } => {
            if current {
                // Get the current running entry and delete it
                match api_client.get_current_time_entry_minimal().await? {
                    Some(entry) => DeleteCommand::execute(api_client, entry.id, json).await,
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                // id is guaranteed Some due to validation above
                DeleteCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Search {
            query,
            project,
            no_project,
            tags,
            no_tag,
            since,
            until,
            number,
            order_by,
            order_dir,
            json,
        } => {
            commands::search::execute(
                api_client, query, project, no_project, tags, no_tag, since, until, number,
                order_by, order_dir, json,
            )
            .await
        }
        EntryAction::BulkEdit { ids, json } => {
            // json is guaranteed Some due to validation above
            BulkEditTimeEntriesCommand::execute(api_client, ids.clone(), json.clone().unwrap())
                .await
        }
    }
}

