impl V9ApiClient {
    async fn get_time_entries(
        &self,
        since: Option<&str>,
        until: Option<&str>,
    ) -> ResultWithDefaultError<Vec<NetworkTimeEntry>> {
        let mut url = format!("{}/me/time_entries", self.base_url);
        let mut params: Vec<String> = Vec::new();
        if let Some(since) = since {
            params.push(format!("start_date={since}"));
        }
        if let Some(until) = until {
            params.push(format!("end_date={until}"));
        }
        if !params.is_empty() {
            url = format!("{}?{}", url, params.join("&"));
        }
        self.get::<Vec<NetworkTimeEntry>>(url).await
    }

    async fn get_projects(&self) -> ResultWithDefaultError<Vec<NetworkProject>> {
        // `include_archived=true` is required for `/me/projects` to return archived
        // projects; without it the endpoint silently filters them out, so client-side
        // `--status archived`/`all` filtering would never see them.
        let url = format!("{}/me/projects?include_archived=true", self.base_url);
        self.get::<Vec<NetworkProject>>(url).await
    }

    async fn get_clients(&self) -> ResultWithDefaultError<Vec<NetworkClient>> {
        let url = format!("{}/me/clients", self.base_url);
        self.get::<Vec<NetworkClient>>(url).await
    }

    async fn get_tasks(&self) -> ResultWithDefaultError<Vec<NetworkTask>> {
        let url = format!("{}/me/tasks", self.base_url);
        self.get::<Vec<NetworkTask>>(url).await
    }

    async fn get_workspaces(&self) -> ResultWithDefaultError<Vec<NetworkWorkspace>> {
        let url = format!("{}/me/workspaces", self.base_url);
        self.get::<Vec<NetworkWorkspace>>(url).await
    }

    async fn get_workspace_tags(
        &self,
        workspace_id: i64,
    ) -> ResultWithDefaultError<Vec<NetworkTag>> {
        let url = format!("{}/workspaces/{}/tags", self.base_url, workspace_id);
        self.get::<Vec<NetworkTag>>(url).await

    pub fn get_duration_hmmss(&self) -> String {
        let duration = self.get_duration();
        format!(
            "{}:{:02}:{:02}",
            duration.num_hours(),
            duration.num_minutes() % 60,
            duration.num_seconds() % 60
        )
    }

    pub fn is_running(&self) -> bool {
        self.duration.is_negative()
    }

    pub fn as_running_time_entry(&self, start: DateTime<Utc>) -> TimeEntry {
        TimeEntry {
            start,
            stop: None,
            duration: -start.timestamp(),
            created_with: Some(constants::CLIENT_NAME.to_string()),
            ..self.clone()
        }
    }

    pub fn get_display_tags(&self) -> String {
        if self.tags.is_empty() {
            "".to_string()
        } else {
            format!("[{}]", self.tags.join(", "))
        }
    }
}

impl Default for TimeEntry {
    fn default() -> Self {
        let start = Utc::now();
        Self {
            id: -1,
            created_with: Some(constants::CLIENT_NAME.to_string()),
            billable: false,
            description: "".to_string(),
            duration: -start.timestamp(),
            project: None,
            start,
            stop: None,
            tags: Vec::new(),
            task: None,
            workspace_id: -1,
        }
    }
}

impl std::fmt::Display for TimeEntry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let local_start: DateTime<Local> = self.start.with_timezone(&Local);
        let time_str = match self.stop {
            Some(stop) => {
                let local_stop: DateTime<Local> = stop.with_timezone(&Local);
                let cross_day = local_stop.date_naive() != local_start.date_naive();
                if cross_day {
                    format!(
                        "{} ~ {}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%m-%d %H:%M")
                    )
                } else {
                    format!(
                        "{}~{}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%H:%M")
                    )
                }
            }
            None => format!("{}~…", local_start.format("%Y-%m-%d %H:%M")),
        };
        let summary = format!(
            //{id} {date HH:MM–HH:MM} {$/space} [{duration}]{running indicator/space} – {description}{@project} {#tags}
            "{} {} {} [{}]{} –  {}{} {}",
            self.id,
            time_str,
            if self.billable {
                "$".green().bold().to_string()
            } else {
                " ".to_string()
            },
            if self.is_running() {
                self.get_duration_hmmss().green().bold()
            } else {
                self.get_duration_hmmss().normal()
            },
            if self.is_running() { "*" } else { " " },
            self.get_description().replace('\n', " "),
            match self.project.clone() {
                Some(p) => format!(" @{p}"),
                None => "".to_string(),
            },
            if self.tags.is_empty() {
                "".to_string()
            } else {
                format!("#{}", self.get_display_tags().italic())
            }
        );
        write!(f, "{summary}")
    }
}

