use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::BTreeMap;

pub struct InvoiceMonthlyCommand;

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let monthly = billable_seconds_by_month(&entries);

        if monthly.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = monthly.values().sum();
        for (month, seconds) in monthly {
            println!("{month}  {seconds}s");
        }
        println!("Total  {total}s");
        Ok(())
    }
}

fn billable_seconds_by_month(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut monthly = BTreeMap::new();

    for entry in entries {
        // The invoice rule counts only completed billable entries with positive duration.
        if !entry.billable || entry.is_running() || entry.duration <= 0 {
            continue;
        }

        let month = entry.start.format("%Y-%m").to_string();
        *monthly.entry(month).or_insert(0) += entry.duration;
    }

    monthly
}

#[cfg(test)]
mod tests {
    use super::billable_seconds_by_month;
    use crate::models::TimeEntry;
    use chrono::DateTime;

    fn entry(start: &str, duration: i64, billable: bool, stop: bool) -> TimeEntry {
        let start: DateTime<chrono::FixedOffset> = start.parse().expect("valid datetime");
        let start = start.with_timezone(&chrono::Utc);
        TimeEntry {
            id: 1,
            description: String::new(),
            start,
            stop: stop.then_some(start + chrono::Duration::seconds(duration)),
            duration,
            billable,
            workspace_id: 1,
            tags: Vec::new(),
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn groups_billable_stopped_entries_by_utc_month_oldest_first() {
        let entries = vec![
            entry("2026-02-01T00:00:00Z", 20, true, true),
            entry("2025-12-31T23:30:00-02:00", 30, true, true),
            entry("2026-02-10T00:00:00Z", 40, false, true),
            entry("2026-02-11T00:00:00Z", -1, true, false),
        ];

        let grouped = billable_seconds_by_month(&entries);
        let values: Vec<_> = grouped.into_iter().collect();
        assert_eq!(
            values,
            vec![("2026-01".to_string(), 30), ("2026-02".to_string(), 20)]
        );
    }

    #[test]
    fn excludes_zero_and_negative_durations() {
        let entries = vec![
            entry("2026-01-01T00:00:00Z", 0, true, true),
            entry("2026-01-02T00:00:00Z", -1, true, false),
        ];
        assert!(billable_seconds_by_month(&entries).is_empty());
    }
}

