use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use serde::Serialize;
use std::collections::BTreeMap;

pub struct InvoiceMonthlyCommand;

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let monthly = billable_seconds_by_month(&entries);
        let total: i64 = monthly.values().sum();

        if json {
            let months = monthly
                .iter()
                .map(|(month, seconds)| InvoiceMonth {
                    month: month.clone(),
                    billable_seconds: *seconds,
                })
                .collect();
            let output = InvoiceMonthlyOutput {
                months,
                total_billable_seconds: total,
            };
            println!(
                "{}",
                serde_json::to_string(&output).expect("failed to serialize invoice to JSON")
            );
            return Ok(());
        }

        if monthly.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        for (month, seconds) in monthly {
            println!("{month}  {seconds}s");
        }
        println!("Total  {total}s");
        Ok(())
    }
}

#[derive(Serialize)]
struct InvoiceMonthlyOutput {
    months: Vec<InvoiceMonth>,
    total_billable_seconds: i64,
}

#[derive(Serialize)]
struct InvoiceMonth {
    month: String,
    billable_seconds: i64,
}

fn billable_seconds_by_month(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut monthly = BTreeMap::new();

    for entry in entries {
        // The invoice rule counts only completed billable entries with positive duration.
        if !entry.billable || entry.is_running() || entry.duration <= 0 {
            continue;
        }

        let month = entry.start.format("%Y-%m").to_string();
        *monthly.entry(month).or_insert(0) += entry.duration;
    }

    monthly
}

